'use strict';

// MODULES //

var tape = require( 'tape' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var factory = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor throws an error if a byte offset is misaligned', function test( t ) {
	var Float32ArrayFE;
	var Int16ArrayFE;

	Float32ArrayFE = factory( 'float32' );
	Int16ArrayFE = factory( 'int16' );

	t.throws( badValue1, RangeError, 'throws expected error' );
	t.throws( badValue2, RangeError, 'throws expected error' );
	t.throws( badValue3, RangeError, 'throws expected error' );
	t.end();

	function badValue1() {
		return new Float32ArrayFE( 'little-endian', new ArrayBuffer( 16 ), 2 );
	}

	function badValue2() {
		return new Float32ArrayFE( 'little-endian', new ArrayBuffer( 16 ), 2, 2 );
	}

	function badValue3() {
		return new Int16ArrayFE( 'little-endian', new ArrayBuffer( 8 ), 1, 1 );
	}
});

tape( 'the constructor throws an error if implicit view length is misaligned', function test( t ) {
	var Float32ArrayFE;
	var Float64ArrayFE;

	Float32ArrayFE = factory( 'float32' );
	Float64ArrayFE = factory( 'float64' );

	t.throws( badValue1, RangeError, 'throws expected error' );
	t.throws( badValue2, RangeError, 'throws expected error' );
	t.end();

	function badValue1() {
		return new Float32ArrayFE( 'little-endian', new ArrayBuffer( 10 ), 4 );
	}

	function badValue2() {
		return new Float64ArrayFE( 'little-endian', new ArrayBuffer( 12 ), 0 );
	}
});

tape( 'the constructor allows trailing bytes when provided an explicit length', function test( t ) {
	var Float32ArrayFE;
	var arr;

	Float32ArrayFE = factory( 'float32' );

	arr = new Float32ArrayFE( 'little-endian', new ArrayBuffer( 10 ), 0, 2 );
	t.strictEqual( arr.length, 2, 'returns expected value' );
	t.strictEqual( arr.byteLength, 8, 'returns expected value' );
	t.strictEqual( arr.byteOffset, 0, 'returns expected value' );

	t.end();
});

tape( 'the constructor allows a byte offset equal to the buffer byte length', function test( t ) {
	var Float32ArrayFE;
	var arr;

	Float32ArrayFE = factory( 'float32' );

	arr = new Float32ArrayFE( 'little-endian', new ArrayBuffer( 12 ), 12 );
	t.strictEqual( arr.length, 0, 'returns expected value' );
	t.strictEqual( arr.byteLength, 0, 'returns expected value' );
	t.strictEqual( arr.byteOffset, 12, 'returns expected value' );

	t.end();
});
